from collections import deque

def {{fn_name}}(node, NodeClass):
    if not node: return None
    mapping = {node: NodeClass(node.val)}
    q = deque([node])
    while q:
        u = q.popleft()
        for nb in u.neighbors:
            if nb not in mapping:
                mapping[nb] = NodeClass(nb.val)
                q.append(nb)
            mapping[u].neighbors.append(mapping[nb])
    return mapping[node]
